+    use super::*;
+
+    #[test]
+    fn endpoints() {
+        let base = Url::parse("https://o1.com/iceberg").unwrap();
+        let endpoints = Endpoints::new(base, "arn");
+
+        assert_eq!(
+            "https://o1.com/iceberg/v1/config",
+            endpoints.v1_config().unwrap().as_str()
+        );
