+        assert_eq!(
+            "https://o1.com/iceberg/v1/arn/namespaces",
+            endpoints.v1_namespaces().unwrap().as_str()
+        );
+
+        assert_eq!(
+            "https://o1.com/iceberg/v1/arn/namespaces/my_ns",
+            endpoints.v1_namespaces_namespace("my_ns").unwrap().as_str()
