+function buildMdFromAnswer(answer: AnswerAction) {
+  let refStr = '';
+  if (answer.references?.length > 0) {
+    refStr = `
+
+## References
+${answer.references.map((ref, i) => `
+${i + 1}. [${ref.exactQuote}](${ref.url})`).join('')}`;
+  }
+  return `${answer.answer.replace(/\(REF_(\d+)\)/g, (_, num) => `[^${num}]`)}${refStr}`;
+}
