+        }
+        
+        throw new Error(`Failed to fetch usage stats: ${response.status}`);
+      }
+      
+      const data = await response.json();
+      return data;
+      
+    } catch (error) {
+      logger.error("Failed to fetch usage statistics", error);
+      return null;
+    }
