+        ...context,
+        ...extra,
+        timestamp: new Date().toISOString()
+      }));
+    },
+    error: (message: string, error: any, extra = {}) => {
+      console.error(JSON.stringify({
+        level: 'error',
+        message,
+        error: error?.message,
+        stack: error?.stack,
+        ...context,
+        ...extra,
+        timestamp: new Date().toISOString()
+      }));
+    }
+  };
