+    logger.info('Token limit exceeded', { userId, remaining, usage, limit });
+    throw new AuthorizationError(
+      `Token limit exceeded. Used ${usage}/${limit} tokens. Please upgrade your plan for more tokens.`,
+      429
+    );
+  }
+  
+  return { remaining };
