+        Default::default(),
+    )
+    .await;
+
+    dbg!(&messages);
+
+    assert!(messages.len() == 2);
+
+    assert!(messages[0].content == Some("You are a helpful asistant".to_string()));
+    assert!(messages[1].content == Some("How are you today?".to_string()));
+}

