+                                    required: true
+                                }
+                            }
+                            div {
+                                class: "form-group",
+                                label {
+                                    class: "label",
+                                    "for": "description",
+                                    "Description"
+                                }
+                                textarea {
+                                    class: "textarea",
+                                    id: "description",
+                                    name: "description",
+                                    placeholder: "Enter workflow description",
+                                    rows: "3"
