+                                    class: "label",
+                                    "for": "trigger_type",
+                                    "Trigger Type"
+                                }
+                                select {
+                                    class: "select",
+                                    id: "trigger_type",
+                                    name: "trigger_type",
+                                    option { value: "file_upload", "File Upload" }
+                                    option { value: "api_call", "API Call" }
