+            let tool = ExternalIntegrationTool::new(
+                tool_def,
+                base_url.clone(),
+                oas3.clone(),
+                operation_id,
+            );
+            tools.push(Arc::new(tool));
+        }
+    } else {
+        return Err("Integration doesn't have a definition".to_string());
+    }
+
+    Ok(tools)
+}
