+            .collect::<Vec<_>>()
+            .join("\n\n");
+
+        Ok(json!({
+            "content": combined_text,
+            "section_index": start_index,
+            "section_count": selected_sections.len(),
+            "total_sections": total_sections,
+            "has_next": end_index < total_sections,
+            "has_prev": start_index > 0,
+            "mime_type": content.mime_type
+        }))
+    }
+}

