+        let spec_json = json!({
+            "openapi": "3.0.0",
+            "info": {"title": "Test API", "version": "1.0"},
+            "paths": {"/users": {"get": {"summary": "list"}}}
+        })
+        .to_string();
+
+        let result = parse_openapi_spec(&spec_json);
+        assert!(result.is_err());
+    }
+
