+                                    button_scheme: ButtonScheme::Error,
+                                    "Cancel"
+                                }
+                                Button {
+                                    button_type: ButtonType::Submit,
+                                    button_scheme: ButtonScheme::Primary,
+                                    "Save Dataset Connections"
+                                }
+                            }
+                        }
+                    }
+                }
+            }
+        }
+    };
+
+    crate::render(page)
